def separate_paren_groups(paren_string: str) -> List[str]:
    def extract_groups(paren_string):
        groups = []
        group = ''
        open_count = 0
        for char in paren_string:
            if char == '(':
                open_count += 1
                if open_count == 1:
                    group += char
            elif char == ')':
                open_count -= 1
                if open_count == 0:
                    group += char
                    groups.append(group)
                    group = ''
            elif open_count > 0:
                group += char
        return groups

    def remove_spaces(groups):
        return [group.replace(' ', '') for group in groups]

    def is_balanced(group):
        stack = []
        for char in group:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack or stack.pop() != '(':
                    return False
        return not stack

    groups = extract_groups(paren_string)
    groups = remove_spaces(groups)
    return [group for group in groups if is_balanced(group)]

